ciphertext = bytes.fromhex("")
key = bytes.fromhex("636f6d7075746572656e6e65747765726b7365637572697479697374686562657374636f75727365")

plaintext = bytearray()
for i in range(len(ciphertext)):
    plaintext.append(ciphertext[i] ^ key[i % len(key)])

print(plaintext.decode("utf-8"))

hex_string = plaintext.decode("utf-8")
print(bytes.fromhex(hex_string).decode("utf-8"))